from __future__ import annotations

from fastapi import APIRouter, Request
from fastapi.responses import HTMLResponse

from .branding import ENDORSEMENT, PRODUCT_FULL_NAME

router = APIRouter()


def _page(kind: str, request: Request) -> HTMLResponse:
    member = getattr(request.state, "member", None)
    plan = getattr(getattr(member, "plan", None), "id", "member").upper()
    if kind == "video":
        title = "Aura Video Studio"
        icon = "🎬"
        headline = "Direct video scene by scene."
        description = (
            "Build music videos, social video and cinematic sequences as editable project elements. "
            "Aura keeps each scene addressable so one change does not have to destroy the rest of the project."
        )
        operation_options = ["create", "storyboard", "revise", "replace", "extend", "transform", "sync", "style"]
        defaults = {"width": 1920, "height": 1080, "frames": 121, "fps": 24}
    else:
        title = "Aura Image Designer"
        icon = "🎨"
        headline = "Design, revise and preserve the details."
        description = (
            "Create covers, posters, campaign artwork and visual assets with editable Creative DNA. "
            "Aura can target the exact element you identify while keeping protected elements unchanged."
        )
        operation_options = ["create", "revise", "replace", "transform", "style", "analyze"]
        defaults = {"width": 1024, "height": 1024, "frames": 1, "fps": 1}
    operation_html = "".join(f"<option>{value}</option>" for value in operation_options)
    media_settings = (
        f"""<div class='row4'><label>Width<input id='width' type='number' value='{defaults['width']}' min='64' max='4096'></label><label>Height<input id='height' type='number' value='{defaults['height']}' min='64' max='4096'></label><label>Frames<input id='frames' type='number' value='{defaults['frames']}' min='1' max='10000'></label><label>FPS<input id='fps' type='number' value='{defaults['fps']}' min='1' max='120' step='0.1'></label></div>"""
        if kind == "video"
        else f"""<div class='row'><label>Width<input id='width' type='number' value='{defaults['width']}' min='64' max='4096'></label><label>Height<input id='height' type='number' value='{defaults['height']}' min='64' max='4096'></label></div><input id='frames' type='hidden' value='1'><input id='fps' type='hidden' value='1'>"""
    )
    html = r"""<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1,viewport-fit=cover'><meta name='robots' content='noindex,nofollow'><title>__TITLE__ — __PRODUCT__</title><style>
:root{--bg:#04050b;--panel:#101321;--line:#ffffff1d;--gold:#f4c873;--violet:#a66bff;--cyan:#5de7ff;--pink:#ff74d0;--green:#78dda7;--warn:#ffd37f;--bad:#ff92a5;--text:#fff;--muted:#bbc0d2}*{box-sizing:border-box}body{margin:0;color:#fff;font-family:Inter,ui-sans-serif,system-ui,sans-serif;background:radial-gradient(circle at 9% 0,#32134c,transparent 30%),radial-gradient(circle at 93% 3%,#11384f,transparent 27%),#04050b;min-height:100vh}a{color:inherit;text-decoration:none}button,input,textarea,select{font:inherit}.wrap{width:min(1400px,calc(100% - 28px));margin:auto;padding:24px 0 55px}.top,.row{display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap}.brand{font-weight:950}.brand small{display:block;color:var(--gold);font-size:.65rem;text-transform:uppercase;letter-spacing:.08em}.btn,button{display:inline-block;border:1px solid var(--line);border-radius:11px;padding:10px 13px;background:#ffffff08;color:#fff;font-weight:850;cursor:pointer}.btn:hover,button:hover{border-color:#ffffff42}.btn:disabled,button:disabled{opacity:.48;cursor:not-allowed}.primary{border:0;background:linear-gradient(110deg,#fff0ae,var(--gold),#c6a0ff);color:#160b1d}.danger{border-color:#ff92a566;background:#4a111b55;color:#ffd7dd}.danger:hover{border-color:var(--bad)}.hero{padding:45px 0 22px}.eyebrow{font-size:.72rem;color:var(--gold);font-weight:950;letter-spacing:.16em;text-transform:uppercase}h1{font-size:clamp(2.7rem,6vw,5.3rem);letter-spacing:-.06em;line-height:.93;margin:.12em 0 .2em}h1 span{background:linear-gradient(100deg,#fff,var(--gold),var(--pink),var(--cyan));background-clip:text;color:transparent}.lead,.muted{color:var(--muted);line-height:1.6}.layout{display:grid;grid-template-columns:.9fr 1.1fr;gap:13px}.panel{border:1px solid var(--line);border-radius:21px;background:linear-gradient(145deg,#111426e8,#080a14ed);padding:17px}.stack{display:grid;gap:9px}.field,input,textarea,select{width:100%;border:1px solid var(--line);border-radius:11px;padding:11px;background:#070913;color:#fff;outline:none}.field:focus,input:focus,textarea:focus,select:focus{border-color:var(--violet)}textarea{min-height:105px;resize:vertical}label{font-size:.78rem;color:var(--muted);font-weight:750}.row{display:grid;grid-template-columns:1fr 1fr;gap:8px}.row4{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.notice{display:none;border:1px solid var(--line);border-radius:12px;padding:11px;margin-bottom:11px}.notice.show{display:block}.notice.error{color:#ffd6dd;border-color:#ff92a555}.status{border:1px solid var(--line);border-radius:15px;padding:13px;background:#ffffff05}.status strong{display:block}.pill{display:inline-block;border:1px solid var(--line);border-radius:999px;padding:4px 7px;font-size:.68rem;margin:2px}.good{color:var(--green)}.warn{color:var(--warn)}.bad{color:var(--bad)}.list{display:grid;gap:8px;margin-top:11px}.item{border:1px solid var(--line);border-radius:15px;padding:12px;background:#ffffff04;transition:border-color .2s,background .2s}.item.state-running,.item.state-queued{border-color:#f4c87344;background:#f4c87308}.item.state-completed{border-color:#78dda744}.item.state-failed{border-color:#ff92a555}.itemtop{display:flex;justify-content:space-between;gap:8px;align-items:start}.id{font:600 .68rem ui-monospace,SFMono-Regular,Menlo,monospace;color:#8f94a9;word-break:break-all}.source{color:var(--cyan);font-size:.72rem;word-break:break-all}.actions{display:flex;gap:7px;flex-wrap:wrap;margin-top:8px}.empty{border:1px dashed #ffffff29;border-radius:14px;padding:20px;text-align:center;color:var(--muted)}.renderstate{margin-top:8px;padding:9px 10px;border:1px solid var(--line);border-radius:11px;background:#060812}.renderline{display:flex;align-items:center;gap:8px;font-size:.76rem;font-weight:800}.renderdot{width:8px;height:8px;flex:0 0 8px;border-radius:50%;background:var(--gold);box-shadow:0 0 0 0 #f4c87377;animation:pulse 1.4s infinite}.progress{height:4px;overflow:hidden;border-radius:999px;background:#ffffff10;margin-top:8px}.progress:after{content:'';display:block;height:100%;width:38%;border-radius:999px;background:linear-gradient(90deg,var(--violet),var(--gold),var(--cyan));animation:sweep 1.45s ease-in-out infinite}.renderdetail{display:block;color:var(--muted);font-size:.7rem;line-height:1.4;margin-top:5px}.live-monitor{font-size:.7rem;color:var(--muted);margin-top:7px}.ready{color:var(--green);font-weight:850}.busy{opacity:.68}@keyframes pulse{0%{box-shadow:0 0 0 0 #f4c87366}70%{box-shadow:0 0 0 8px #f4c87300}100%{box-shadow:0 0 0 0 #f4c87300}}@keyframes sweep{0%{transform:translateX(-120%)}100%{transform:translateX(300%)}}@media(max-width:900px){.layout{grid-template-columns:1fr}}@media(max-width:650px){.row,.row4{grid-template-columns:1fr 1fr}}@media(max-width:450px){.row,.row4{grid-template-columns:1fr}}
</style></head><body><main class='wrap'><header class='top'><a class='brand' href='/dashboard'>__PRODUCT__<small>__ENDORSEMENT__</small></a><div><a class='btn' href='/creative-house'>Unified Creative House</a> <a class='btn' href='/dashboard'>Dashboard</a></div></header><section class='hero'><div class='eyebrow'>__ICON__ __TITLE__ · __PLAN__</div><h1>__HEADLINE_FIRST__ <span>__HEADLINE_LAST__</span></h1><p class='lead'>__DESCRIPTION__</p></section><div id='notice' class='notice' role='status' aria-live='polite'></div><section class='layout'><div class='panel'><div class='eyebrow'>Project setup</div><h2>Start or open a __KIND__ project</h2><div class='stack'><input id='project' placeholder='Project ID, e.g. release-visuals'><input id='title' placeholder='Project title'><textarea id='intent' placeholder='What are you creating and why?'></textarea><div class='actions'><button class='primary' onclick='initProject()'>Initialize Project</button><button onclick='loadProject()'>Load Project</button></div></div><hr style='border:0;border-top:1px solid var(--line);margin:18px 0'><div class='eyebrow'>Authorised reference</div><h3>Attach a project reference</h3><div class='stack'><input id='refLabel' placeholder='Reference label'><input id='refSource' placeholder='Existing project asset ID / authorised reference'><input id='refUsage' placeholder='How Aura should use it'><label><input id='refRights' type='checkbox' style='width:auto'> I own or am authorised to use this reference.</label><button onclick='addReference()'>Attach Reference</button></div></div><div class='panel'><div class='eyebrow'>Aura direction</div><h2>Make a precise __KIND__ instruction</h2><p class='muted'>Tell Aura what to create or change. Target/preserve IDs let a future revision stay local instead of replacing unrelated project elements.</p><div class='stack'><div class='row'><label>Operation<select id='operation'>__OPERATIONS__</select></label><label>Target kind<input value='__KIND__' disabled></label></div><input id='targetIds' placeholder='Target element IDs, comma separated (optional)'><input id='preserveIds' placeholder='Element IDs to preserve unchanged (optional)'><input id='referenceIds' placeholder='Reference IDs to use (optional)'><textarea id='instruction' placeholder='Describe exactly what Aura should create or change.'></textarea><input id='negative' placeholder='Negative prompt / exclusions (optional)'>__MEDIA_SETTINGS__<button class='primary' onclick='addDirective()'>Add Aura Directive</button></div><div id='engine' class='status' style='margin-top:12px'><strong>Renderer state</strong><span class='muted'>Checking __KIND__ engine configuration…</span></div><div id='directives' class='list'><div class='empty'>Load a project to see Aura directives and generated outputs.</div></div></div></section></main><script>
const KIND='__KIND__',POLL_MS=3000,q=id=>document.getElementById(id);let manifest=null,renderers={},pollTimer=null,pollBusy=false;const directiveBusy=new Set(),pollErrors=new Map(),announcedTerminal=new Set();function ids(v){return v.split(',').map(x=>x.trim()).filter(Boolean)}function notice(m,e=false){const n=q('notice');n.textContent=m;n.className='notice show'+(e?' error':'');clearTimeout(window.__n);window.__n=setTimeout(()=>n.className='notice',7000)}async function api(path,opt={}){const r=await fetch(path,{credentials:'same-origin',headers:{'Content-Type':'application/json'},...opt});let b={};try{b=await r.json()}catch(e){}if(!r.ok)throw new Error(b.detail||`Request failed (${r.status})`);return b}function project(){return q('project').value.trim()}function upsertDirective(d){if(!manifest||!d)return;const rows=manifest.directives||[];const i=rows.findIndex(x=>x.id===d.id);if(i>=0)rows[i]=d;else rows.push(d);manifest.directives=rows}function activeDirectives(){return (manifest?.directives||[]).filter(d=>d.target_kind===KIND&&['queued','running'].includes(d.status))}function stopMonitor(){if(pollTimer){clearInterval(pollTimer);pollTimer=null}}function ensureMonitor(){const active=activeDirectives();if(active.length&&!pollTimer)pollTimer=setInterval(()=>void pollActiveRenders(),POLL_MS);if(!active.length)stopMonitor()}async function capabilities(probe=false){try{const d=await api(`/creative/renderers?probe=${probe?'true':'false'}`);renderers=d.renderers||{};renderEngine()}catch(e){notice(e.message,true)}}function renderEngine(){const r=renderers[KIND]||{};q('engine').innerHTML=`<strong>${KIND==='video'?'🎬':'🎨'} ${KIND} renderer</strong><span class="${r.connected?'good':'muted'}">${r.connected?'Connected':r.configured?'Configured — probe to confirm live engine':'Adapter installed; deployment workflow not configured yet.'}</span><div class="live-monitor">Live render monitor · checks active jobs automatically every ${POLL_MS/1000} seconds while this tab is visible.</div><div class="actions"><button onclick="capabilities(true)">Probe Engine</button></div>`;render()}async function initProject(){if(!project())return notice('Enter a project ID.',true);try{const d=await api(`/creative/projects/${encodeURIComponent(project())}/initialize`,{method:'POST',body:JSON.stringify({title:q('title').value.trim()||project(),project_intent:q('intent').value.trim()})});manifest=d.manifest;renderers=d.creative_renderers||renderers;renderEngine();notice('Project initialized.');void pollActiveRenders(true)}catch(e){notice(e.message,true)}}async function loadProject(silent=false){if(!project())return silent?null:notice('Enter a project ID.',true);try{const d=await api(`/creative/projects/${encodeURIComponent(project())}/manifest`);manifest=d.manifest;renderers=d.creative_renderers||renderers;q('title').value=manifest.title||'';q('intent').value=manifest.project_intent||'';renderEngine();if(!silent)notice('Project loaded.');if(activeDirectives().length)void pollActiveRenders(true);return d}catch(e){if(!silent)notice(e.message,true);return null}}async function addReference(){if(!manifest)return notice('Load or initialize the project first.',true);if(!q('refRights').checked)return notice('Rights/authorization confirmation is required.',true);try{const d=await api(`/creative/projects/${encodeURIComponent(project())}/references`,{method:'POST',body:JSON.stringify({kind:KIND,label:q('refLabel').value.trim(),source_ref:q('refSource').value.trim(),usage:q('refUsage').value.trim()||'creative reference',rights_confirmed:true})});manifest=d.manifest;q('refLabel').value='';q('refSource').value='';q('refUsage').value='';q('refRights').checked=false;render();notice('Reference attached.')}catch(e){notice(e.message,true)}}async function addDirective(){if(!manifest)return notice('Load or initialize the project first.',true);const instruction=q('instruction').value.trim();if(!instruction)return notice('Tell Aura what to create or change.',true);try{const d=await api(`/creative/projects/${encodeURIComponent(project())}/directives`,{method:'POST',body:JSON.stringify({instruction,input_mode:'text',operation:q('operation').value,target_kind:KIND,target_element_ids:ids(q('targetIds').value),preserve_element_ids:ids(q('preserveIds').value),reference_ids:ids(q('referenceIds').value)})});manifest=d.manifest;q('instruction').value='';render();notice(d.truthful_execution_state.note)}catch(e){notice(e.message,true)}}async function queue(id){if(directiveBusy.has(id))return;directiveBusy.add(id);render();try{const d=await api(`/creative/projects/${encodeURIComponent(project())}/directives/${id}/render`,{method:'POST',body:JSON.stringify({negative_prompt:q('negative').value.trim(),width:Number(q('width').value),height:Number(q('height').value),frames:Number(q('frames').value),fps:Number(q('fps').value)})});upsertDirective(d.directive);pollErrors.delete(id);announcedTerminal.delete(id);render();notice(d.note||'Render queued.');void pollActiveRenders(true)}catch(e){notice(e.message,true)}finally{directiveBusy.delete(id);render()}}async function check(id){if(directiveBusy.has(id))return;directiveBusy.add(id);render();try{const d=await api(`/creative/projects/${encodeURIComponent(project())}/directives/${id}/render-status`);upsertDirective(d.directive);pollErrors.delete(id);render();notice(`Renderer status: ${d.renderer_status}. ${d.outputs.length} output(s).`)}catch(e){pollErrors.set(id,e.message);render();notice(e.message,true)}finally{directiveBusy.delete(id);render()}}async function cancelRender(id){if(directiveBusy.has(id))return;directiveBusy.add(id);render();try{const d=await api(`/creative/projects/${encodeURIComponent(project())}/directives/${id}/cancel-render`,{method:'POST'});upsertDirective(d.directive);pollErrors.delete(id);announcedTerminal.delete(id);render();notice(d.note||'Render cancelled safely.')}catch(e){pollErrors.set(id,e.message);render();notice(e.message,true)}finally{directiveBusy.delete(id);render()}}async function sync(id){if(directiveBusy.has(id))return;directiveBusy.add(id);render();try{const d=await api(`/creative/projects/${encodeURIComponent(project())}/directives/${id}/sync-outputs`,{method:'POST'});upsertDirective(d.directive);pollErrors.delete(id);render();notice(`${d.imported_elements.length} output(s) imported into Creative DNA.`);await loadProject(true)}catch(e){notice(e.message,true)}finally{directiveBusy.delete(id);render()}}async function pollActiveRenders(force=false){if(pollBusy||!manifest||(!force&&document.hidden))return;const active=activeDirectives();if(!active.length){ensureMonitor();return}pollBusy=true;try{for(const d of active){if(directiveBusy.has(d.id))continue;try{const s=await api(`/creative/projects/${encodeURIComponent(project())}/directives/${d.id}/render-status`);upsertDirective(s.directive);pollErrors.delete(d.id);if(['completed','failed'].includes(s.renderer_status)&&!announcedTerminal.has(d.id)){announcedTerminal.add(d.id);notice(s.renderer_status==='completed'?`${KIND==='video'?'Video':'Image'} render complete — ${s.outputs.length} output(s) ready to import.`:'Creative render failed. Review the directive or renderer and try again.',s.renderer_status==='failed')}}catch(e){pollErrors.set(d.id,e.message)}}render()}finally{pollBusy=false;ensureMonitor()}}function statusBlock(d){const meta=d.metadata?.creative_renderer||{},error=pollErrors.get(d.id);if(['queued','running'].includes(d.status)){const label=d.status==='running'?'Aura is rendering now':'Render queued';return `<div class="renderstate" role="status"><div class="renderline"><span class="renderdot"></span><span>${label}</span></div><div class="progress" aria-hidden="true"></div><span class="renderdetail">${error?`Live status temporarily unavailable: ${esc(error)}. Retrying automatically.`:'Live status is updating automatically. You can leave the controls alone unless you want to cancel or refresh immediately.'}</span></div>`}if(d.status==='completed'&&!meta.synced)return `<div class="renderstate"><span class="ready">✓ Render complete · ${Number(meta.output_count||0)} output(s) ready to import</span></div>`;if(d.status==='failed')return `<div class="renderstate"><span class="bad">Render failed${meta.error?`: ${esc(meta.error)}`:'.'}</span></div>`;if(meta.cancelled&&d.status==='ready_for_renderer')return `<div class="renderstate"><span class="warn">Last render cancelled safely. Revise the Aura directive or render it again when ready.</span></div>`;return ''}function actions(d){const busy=directiveBusy.has(d.id),disabled=busy?' disabled':'';if(d.status==='completed'&&d.metadata?.creative_renderer?.synced)return '<span class="pill good">Outputs imported</span>';if(d.status==='completed')return `<button class="primary" onclick="sync('${d.id}')"${disabled}>${busy?'Importing…':'Import outputs'}</button>`;if(['queued','running'].includes(d.status))return `<button onclick="check('${d.id}')"${disabled}>Refresh now</button><button class="danger" onclick="cancelRender('${d.id}')"${disabled}>${busy?'Working…':'Cancel render'}</button>`;if(renderers[KIND]?.configured)return `<button class="primary" onclick="queue('${d.id}')"${disabled}>${busy?'Starting…':`Render ${KIND}`}</button>`;return `<button disabled>${KIND} renderer not configured</button>`}function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function render(){if(!manifest){stopMonitor();return}const dirs=(manifest.directives||[]).filter(d=>d.target_kind===KIND).reverse(),outputs=(manifest.elements||[]).filter(e=>e.kind===KIND);q('directives').innerHTML=(dirs.map(d=>`<div class="item state-${esc(d.status)}${directiveBusy.has(d.id)?' busy':''}"><div class="itemtop"><strong>${esc(d.operation)} · ${esc(d.status.replaceAll('_',' '))}</strong><span class="pill ${d.status==='completed'?'good':d.status==='failed'?'bad':['queued','running'].includes(d.status)?'warn':''}">${esc(d.capability_state.replaceAll('_',' '))}</span></div><p class="muted">${esc(d.instruction)}</p>${statusBlock(d)}<div class="actions">${actions(d)}</div><div class="id">${esc(d.id)}</div></div>`).join('')+outputs.map(e=>`<div class="item"><div class="itemtop"><strong>${esc(e.label)}</strong><span class="pill good">${esc(e.status)}</span></div><div class="source">${esc(e.source_ref||'')}</div><div class="id">${esc(e.id)}</div></div>`).join(''))||'<div class="empty">No '+KIND+' directives or outputs yet.</div>';ensureMonitor()}document.addEventListener('visibilitychange',()=>{if(!document.hidden)void pollActiveRenders(true)});window.addEventListener('beforeunload',stopMonitor);capabilities(false);
</script></body></html>"""
    parts = headline.split(" ", 1)
    return HTMLResponse(
        html.replace("__TITLE__", title)
        .replace("__PRODUCT__", PRODUCT_FULL_NAME)
        .replace("__ENDORSEMENT__", ENDORSEMENT)
        .replace("__ICON__", icon)
        .replace("__PLAN__", plan)
        .replace("__HEADLINE_FIRST__", parts[0])
        .replace("__HEADLINE_LAST__", parts[1] if len(parts) > 1 else "")
        .replace("__DESCRIPTION__", description)
        .replace("__KIND__", kind)
        .replace("__OPERATIONS__", operation_html)
        .replace("__MEDIA_SETTINGS__", media_settings)
    )


@router.get("/video-studio", response_class=HTMLResponse, include_in_schema=False)
def video_studio(request: Request):
    return _page("video", request)


@router.get("/image-designer", response_class=HTMLResponse, include_in_schema=False)
def image_designer(request: Request):
    return _page("image", request)
